double monte_carlo_hit_or_miss(FunctionPtr f, double a, double b, double fmax, int n_points, unsigned int& seed) {
    const unsigned int lcg_a = 1664525;
    const unsigned int lcg_c = 1013904223;
    const unsigned int lcg_m = 4294967296U; // 2^32

    int hits = 0;
    for (int i = 0; i < n_points; i++) {
        // Generate random x in [a, b]
        seed = (lcg_a * seed + lcg_c) % lcg_m;
        double x = a + (b - a) * (static_cast<double>(seed) / lcg_m);

        // Generate random y in [0, fmax]
        seed = (lcg_a * seed + lcg_c) % lcg_m;
        double y = fmax * (static_cast<double>(seed) / lcg_m);

        // Check if point is under the curve
        if (y <= f(x)) {
            hits++;
        }
    }

    // Estimate integral: (hits / n_points) * area of rectangle
    return static_cast<double>(hits) / n_points * (b - a) * fmax;
}

